INSERT INTO drugsafe_token (
							token_sn
						  , admin_id
						  , user_id
						  , prgrm_id
						  , updt_token_cn
						  , acs_token_cn
						  , in_admin_id
						  , in_datetime
						  , up_admin_id
						  , up_datetime
				) VALUES (
						   nextval('drugsafe_token_seq')
						 , #{adminId}
						 , #{userId}
						 , #{prgrmId}
						 , #{updtTokenCn}
						 , #{acsTokenCn}
						 , #{inAdminId}
						 , now()
						 , #{upAdminId}
						 , now()
						 )
